question:
Let $AB$ be a diameter of a circle centered at $O$.  Let $E$ be a point on the circle, and let the tangent at $B$ intersect the tangent at $E$ and $AE$ at $C$ and $D$, respectively.  If $\angle BAE = 43^\circ$, find $\angle CED$, in degrees.

[asy]
import graph;

unitsize(2 cm);

pair O, A, B, C, D, E;

O = (0,0);
A = (0,1);
B = (0,-1);
E = dir(-6);
D = extension(A,E,B,B + rotate(90)*(B));
C = extension(E,E + rotate(90)*(E),B,B + rotate(90)*(B));

draw(Circle(O,1));
draw(B--A--D--cycle);
draw(B--E--C);

label("$A$", A, N);
label("$B$", B, S);
label("$C$", C, S);
label("$D$", D, SE);
label("$E$", E, dir(0));
dot("$O$", O, W);
[/asy]

What is the circumference of the circle with center at $P$ and passing through $Q$? Express your answer in terms of $\pi$.

[asy]
size(150); pair P = (-2,3), Q=(10,-2); string stringpair(pair p){return "$("+string(p.x)+", "+string(p.y)+"$)";}
draw((-15,0)--(15,0),Arrows(4)); draw((0,-15)--(0,15),Arrows(4));
dot("$Q$"+stringpair(Q),Q,SE,linewidth(3)); dot("$P$"+stringpair(P),P,NW,linewidth(3));

[/asy]

The graph of $y = f(x)$ is shown below.

[asy]
unitsize(0.5 cm);

real func(real x) {
  real y;
  if (x >= -3 && x <= 0) {y = -2 - x;}
  if (x >= 0 && x <= 2) {y = sqrt(4 - (x - 2)^2) - 2;}
  if (x >= 2 && x <= 3) {y = 2*(x - 2);}
  return(y);
}

int i, n;

for (i = -5; i <= 5; ++i) {
  draw((i,-5)--(i,5),gray(0.7));
  draw((-5,i)--(5,i),gray(0.7));
}

draw((-5,0)--(5,0),Arrows(6));
draw((0,-5)--(0,5),Arrows(6));

label("$x$", (5,0), E);
label("$y$", (0,5), N);

draw(graph(func,-3,3),red);

label("$y = f(x)$", (3,-2), UnFill);
[/asy]

Which is the graph of $y = f(x - 1)$?

[asy]
unitsize(0.5 cm);

picture[] graf;
int i, n;

real func(real x) {
  real y;
  if (x >= -3 && x <= 0) {y = -2 - x;}
  if (x >= 0 && x <= 2) {y = sqrt(4 - (x - 2)^2) - 2;}
  if (x >= 2 && x <= 3) {y = 2*(x - 2);}
  return(y);
}

for (n = 1; n <= 5; ++n) {
  graf[n] = new picture;
  for (i = -5; i <= 5; ++i) {
    draw(graf[n],(i,-5)--(i,5),gray(0.7));
    draw(graf[n],(-5,i)--(5,i),gray(0.7));
  }
  draw(graf[n],(-5,0)--(5,0),Arrows(6));
  draw(graf[n],(0,-5)--(0,5),Arrows(6));

  label(graf[n],"$x$", (5,0), E);
  label(graf[n],"$y$", (0,5), N);
}

draw(graf[1],shift(0,1)*graph(func,-3,3),red);
draw(graf[2],shift(-1,0)*graph(func,-3,3),red);
draw(graf[3],reflect((1,0),(1,1))*graph(func,-3,3),red);
draw(graf[4],shift(1,0)*graph(func,-3,3),red);
draw(graf[5],shift(0,-1)*graph(func,-3,3),red);

label(graf[1], "A", (0,-6));
label(graf[2], "B", (0,-6));
label(graf[3], "C", (0,-6));
label(graf[4], "D", (0,-6));
label(graf[5], "E", (0,-6));

add(graf[1]);
add(shift((12,0))*(graf[2]));
add(shift((24,0))*(graf[3]));
add(shift((6,-12))*(graf[4]));
add(shift((18,-12))*(graf[5]));
[/asy]

Enter the letter of the graph of $y = f(x - 1).$

Triangles $BAD$ and $BDC$ are right triangles with $AB = 12$ units, $BD = 15$ units, and $BC = 17$ units. What is the area, in square units, of quadrilateral $ABCD$?

[asy]
draw((0,0)--(9,0)--(9,0)+8dir(36.87)--(0,12)--cycle,linewidth(1));
draw((0,12)--(9,0),linewidth(1));

label("A",(0,0),SW);
label("B",(0,12),W);
label("C",(9,0)+8dir(36.87),NE);
label("D",(9,0),S);

draw((1,0)--(1,1)--(0,1),linewidth(1));
draw((9,0)+dir(36.87)--(9,0)+sqrt(2)*dir(45+36.87)--(9,0)+dir(36.87+90),linewidth(1));
[/asy]

A circular spinner for a game has a radius of 5 cm. The probability of winning on one spin of this spinner is $\frac{2}{5}$. What is the area, in sq cm, of the WIN sector? Express your answer in terms of $\pi$.

[asy]import graph;
draw(Circle((0,0),25),black);
draw((0,0)--(7,18),Arrow);
draw((0,0)--(0,25));
draw((0,0)--(15,-20));
label("WIN",(10,10),S);
label("LOSE",(-8,-8),N);
dot((0,0));
[/asy]

A sphere is inscribed in a right cone with base radius $12$ cm and height $24$ cm, as shown. The radius of the sphere can be expressed as $a\sqrt{c} - a$ cm. What is the value of $a + c$? [asy]
import three; size(120); defaultpen(linewidth(1)); pen dashes = linetype("2 2") + linewidth(1);
currentprojection = orthographic(0,-1,0.16);
void drawticks(triple p1, triple p2, triple tickmarks) {

draw(p1--p2); draw(p1 + tickmarks-- p1 - tickmarks); draw(p2 + tickmarks -- p2 - tickmarks);
}
real r = 6*5^.5-6;
triple O = (0,0,0), A = (0,0,-24);
draw(scale3(12)*unitcircle3); draw((-12,0,0)--A--(12,0,0)); draw(O--(12,0,0),dashes);
draw(O..(-r,0,-r)..(0,0,-2r)..(r,0,-r)..cycle);
draw((-r,0,-r)..(0,-r,-r)..(r,0,-r)); draw((-r,0,-r)..(0,r,-r)..(r,0,-r),dashes);

drawticks((0,0,2.8),(12,0,2.8),(0,0,0.5));
drawticks((-13,0,0),(-13,0,-24),(0.5,0,0));
label("$12$", (6,0,3.5), N); label("$24$",(-14,0,-12), W);
[/asy]

A sphere is inscribed in a right cone with base radius $12$ cm and height $24$ cm, as shown. The radius of the sphere can be expressed as $a\sqrt{c} - a$ cm. What is the value of $a + c$? [asy]
import three; size(120); defaultpen(linewidth(1)); pen dashes = linetype("2 2") + linewidth(1);
